// Keyed totals: sums values per key and answers queries.
//
// Usage: deno run --allow-read main.ts <input-file>
//
// Keys are compared byte-for-byte, so the input is handled as raw bytes:
// each byte maps to one UTF-16 code unit (0..255) and back on output. That
// keeps invalid UTF-8 and visually-equal-but-different-bytes keys distinct.

const I64_MIN = -(1n << 63n);
const I64_MAX = (1n << 63n) - 1n;
const VALUE_RE = /^[+-]?[0-9]+$/;

type Total = { sum: bigint; overflow: boolean };

function bytesToBinaryString(bytes: Uint8Array): string {
  const parts: string[] = [];
  const CHUNK = 0x8000;
  for (let i = 0; i < bytes.length; i += CHUNK) {
    parts.push(
      String.fromCharCode.apply(
        null,
        bytes.subarray(i, i + CHUNK) as unknown as number[],
      ),
    );
  }
  return parts.join("");
}

function binaryStringToBytes(s: string): Uint8Array {
  const out = new Uint8Array(s.length);
  for (let i = 0; i < s.length; i++) out[i] = s.charCodeAt(i);
  return out;
}

function splitLines(text: string): string[] {
  if (text.length === 0) return [];
  const lines = text.split("\n");
  // A trailing newline terminates the last line rather than starting a new one.
  if (lines[lines.length - 1] === "") lines.pop();
  // Tolerate CRLF line endings.
  for (let i = 0; i < lines.length; i++) {
    const l = lines[i];
    if (l.endsWith("\r")) lines[i] = l.slice(0, -1);
  }
  return lines;
}

/** Computes the program's stdout for the given input file contents. */
export function solve(input: Uint8Array): Uint8Array {
  let text = bytesToBinaryString(input);
  // Strip a UTF-8 byte order mark.
  if (text.startsWith("\xEF\xBB\xBF")) text = text.slice(3);

  const lines = splitLines(text);
  let sep = lines.indexOf("");
  if (sep === -1) sep = lines.length;

  const totals = new Map<string, Total>();
  for (let i = 0; i < sep; i++) {
    const fields = lines[i].split(" ").filter((f) => f !== "");
    if (fields.length !== 2 || !VALUE_RE.test(fields[1])) continue;
    const [key, raw] = fields;
    const value = BigInt(raw);
    let t = totals.get(key);
    if (t === undefined) {
      t = { sum: 0n, overflow: false };
      totals.set(key, t);
    }
    if (t.overflow) continue;
    const next = t.sum + value;
    if (value < I64_MIN || value > I64_MAX || next < I64_MIN || next > I64_MAX) {
      t.overflow = true;
    } else {
      t.sum = next;
    }
  }

  const out: string[] = [];
  for (let i = sep + 1; i < lines.length; i++) {
    const key = lines[i].trim();
    if (key === "") continue;
    const t = totals.get(key);
    let answer: string;
    if (t === undefined) answer = "absent";
    else if (t.overflow) answer = "overflow";
    else answer = t.sum.toString();
    out.push(`${key}=${answer}\n`);
  }
  return binaryStringToBytes(out.join(""));
}

function writeAll(data: Uint8Array): void {
  let off = 0;
  while (off < data.length) off += Deno.stdout.writeSync(data.subarray(off));
}

if (import.meta.main) {
  const path = Deno.args[0];
  if (path === undefined) {
    console.error("usage: main.ts <input-file>");
    Deno.exit(2);
  }
  writeAll(solve(Deno.readFileSync(path)));
}

