cat > main_test.ts <<'EOF'
import { solve } from "./main.ts";

const enc = new TextEncoder();
const dec = new TextDecoder();
const run = (s: string) => dec.decode(solve(enc.encode(s)));

function eq(actual: string, expected: string) {
  if (actual !== expected) {
    throw new Error(`expected ${JSON.stringify(expected)}, got ${JSON.stringify(actual)}`);
  }
}

Deno.test("basic totals and absent", () => {
  eq(run("a 1
b 2
a 3

a
b
c
"), "a=4
b=2
c=absent
");
});

Deno.test("empty input", () => {
  eq(run(""), "");
  eq(run("
"), "");
});

Deno.test("no records, only queries", () => {
  eq(run("
x
"), "x=absent
");
});

Deno.test("no trailing newline and CRLF", () => {
  eq(run("a 5

a"), "a=5
");
});

Deno.test("64-bit extremes are exact", () => {
  eq(
    run("m -9223372036854775808
M 9223372036854775807
z -9223372036854775808
z 9223372036854775807

m
M
z
"),
    "m=-9223372036854775808
M=9223372036854775807
z=-1
",
  );
});

Deno.test("overflow is sticky and order matters", () => {
  eq(run("k 9223372036854775807
k 1
k -5

k
"), "k=overflow
");
  eq(run("k 9223372036854775807
k -1
k 1

k
"), "k=9223372036854775807
");
  eq(run("n -9223372036854775808
n -1

n
n
"), "n=overflow
n=overflow
");
});

Deno.test("unicode keys compared by bytes", () => {
  // precomposed vs decomposed é are different keys
  eq(run("é 1
é 2
кот 3
🐱 4

é
é
кот
🐱
à
"),
    "é=1
é=2
кот=3
🐱=4
à=absent
");
});

Deno.test("invalid UTF-8 bytes round-trip and stay distinct", () => {
  const input = new Uint8Array([0xff, 0x20, 0x31, 0x0a, 0xfe, 0x20, 0x32, 0x0a, 0x0a, 0xff, 0x0a, 0xfe, 0x0a]);
  const out = solve(input);
  const expected = new Uint8Array([0xff, 0x3d, 0x31, 0x0a, 0xfe, 0x3d, 0x32, 0x0a]);
  eq(Array.from(out).join(","), Array.from(expected).join(","));
});

Deno.test("repeated queries", () => {
  eq(run("a -3

a
a
"), "a=-3
a=-3
");
});
EOF
deno check main.ts main_test.ts && deno test 2>&1 | tail -15
printf 'a 1
ä 2
a 9223372036854775807

a
ä
q
' > /tmp/kt.txt && deno run --allow-read main.ts /tmp/kt.txt; echo "exit=$?"
: > /tmp/empty.txt; deno run --allow-read main.ts /tmp/empty.txt; echo "exit=$?"

